"""Reminder vectors (ADR-003, migration batch 1; not part of the shared companion contract), generated by MOSAIC's own
companion_reminders module, so that AIJADE's port (src/Aijade.Client/Companion/Reminders.cs) makes the same promises.

MOSAIC is read-only from this repository: its module is loaded from its file and no bytecode is written. The module uses
the local time zone, so run it with TZ set, as the tests read the same zone back from the file:

    TZ=Asia/Seoul python3 -B -I configs/companion/generate_reminder_vectors.py \
        <MOSAIC>/ai-python/mosaic/integration/companion_reminders.py configs/companion/reminder-vectors.json

The cases cover each way to ask (set, without a usable time, cancel, a question about the ones set, a nickname that is
not a request), relative and clock times with every period word, Chinese numerals, halves and quarters, the minimum lead
time, and the notes and the due line; the file records the source file's SHA-256 and the date read.
"""
import hashlib, importlib.util, json, os, sys, time
sys.dont_write_bytecode = True
src, out = sys.argv[1], sys.argv[2]
zone = os.environ.get("TZ")
if not zone:
    sys.exit("set TZ (for example TZ=Asia/Seoul): the module uses the local time zone")
time.tzset()
spec = importlib.util.spec_from_file_location("companion_reminders", src)
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

NOW = time.mktime((2026, 11, 3, 10, 0, 0, 0, 0, -1))  # Tuesday 3 November 2026, 10:00 local
texts = [
    "十分钟后提醒我喝水", "半小时后叫我", "两个半小时后提醒我休息", "3分钟后提醒我", "一个小时以后喊我", "90秒后提醒我",
    "十秒后提醒我", "八天后提醒我", "一会儿提醒我", "提醒我交作业",
    "明天早上八点叫醒我", "下午3点半提醒我开会", "今晚十点提醒我睡觉", "晚上十二点提醒我", "中午12点提醒我吃饭", "中午一点提醒我",
    "九点提醒我", "8点半提醒我", "10点提醒我", "十点一刻提醒我", "七点三刻叫我起床", "后天上午10点提醒我", "明晚七点叫我",
    "明早6:30叫醒我", "凌晨两点提醒我", "傍晚五点提醒我散步", "夜里十一点提醒我", "下午三点二十分提醒我",
    "取消提醒", "不用叫我了", "你要提醒我什么来着", "你可以叫我小青", "记得提醒我明天带伞", "别让我忘了20分钟后关火",
    "今天天气不错",
]
cases = []
for text in texts:
    found = m.request(text, NOW)
    case = dict(text=text, request=None)
    if found is not None:
        case["request"] = dict(kind=found["kind"])
        if found["kind"] == "set":
            case["request"].update(dueOffsetS=round(found["due"] - NOW), whenWords=found["when_words"],
                                   spokenTime=m.spoken_time(found["due"], NOW))
    cases.append(case)

spoken = [dict(dueOffsetS=s, text=m.spoken_time(NOW + s, NOW)) for s in (60, 13 * 3600 + 59 * 60, 14 * 3600, 2 * 86400, 3 * 86400, 30 * 86400)]
notes = [
    dict(kind="set", when="今天 10:10", cancelled=0, text=m.note(dict(kind="set"), "今天 10:10")),
    dict(kind="unclear", when=None, cancelled=0, text=m.note(dict(kind="unclear"))),
    dict(kind="cancel", when=None, cancelled=2, text=m.note(dict(kind="cancel"), None, 2)),
    dict(kind="cancel", when=None, cancelled=0, text=m.note(dict(kind="cancel"), None, 0)),
]
due_lines = [
    dict(said="十分钟后提醒我喝水", askedAt="今天 09:50", dueAt="今天 10:00", lateS=0, promised="",
         text=m.reminder_note("十分钟后提醒我喝水", "今天 09:50", "今天 10:00", 0)),
    dict(said="明天早上八点叫醒我" * 20, askedAt="昨天 22:00", dueAt="今天 08:00", lateS=900, promised="好的，明天早上八点我会叫醒你。" * 8,
         text=m.reminder_note("明天早上八点叫醒我" * 20, "昨天 22:00", "今天 08:00", 900, "好的，明天早上八点我会叫醒你。" * 8)),
]
with open(src, "rb") as f:
    digest = hashlib.sha256(f.read()).hexdigest()
doc = dict(
    note="Not part of the shared companion contract: AIJADE's port of MOSAIC's reminders (ADR-003). Generated by MOSAIC's own "
         "companion_reminders module; AIJADE's tests require the same result for every case.",
    source=dict(file="ai-python/mosaic/integration/companion_reminders.py (MOSAIC working copy)", sha256=digest, readOn=time.strftime("%Y-%m-%d")),
    timeZone=zone, now=dict(local="2026-11-03 10:00", epoch=NOW),
    constants=dict(ask=list(m.ASK), askWithTime=list(m.ASK_WITH_TIME), query=list(m.QUERY), cancel=list(m.CANCEL),
                   minAheadS=m.MIN_AHEAD_S, maxAheadS=m.MAX_AHEAD_S, lateS=m.LATE_S, dueCue=m.DUE_CUE),
    cases=cases, spokenTimes=spoken, notes=notes, dueLines=due_lines,
)
with open(out, "w", encoding="utf-8") as f:
    json.dump(doc, f, ensure_ascii=False, indent=1)
    f.write("\n")
print(f"{len(cases)} cases, {sum(1 for c in cases if c['request'] and c['request']['kind'] == 'set')} set -> {out}")
